-- Rega24 production data (D1 rega24-migration): the seven missing European target countries, 2026-10-29.
-- Belgium, Switzerland, Greece, Norway, Denmark, Finland and Italy, each with its capital region and capital city.
-- Same rows as prisma/seed-data/geography.ts writes through `npm run db:seed` (checked by tests/seed-data.test.ts).
-- ADDITIVE ONLY: inserts a row only when it is missing (by country code / country + slug / slug or country + English
-- name / region + locale); it never updates or deletes, and running it again changes nothing. New ids start with
-- seed_country_, seed_region_eu_, seed_rt_eu_ and seed_city_eu_, so the change can be undone exactly by deleting
-- those ids (no business or location refers to them yet).
-- Rehearsed on an in-memory SQLite built from prisma/d1/migrations with the pre-change countries: +7 countries,
-- +7 regions, +14 region names, +7 cities, FK check clean, second run no-op, undo below restores the exact counts.
-- Undo (only the rows this file created; skips any row a location, city or region already uses):
--   DELETE FROM City WHERE id LIKE 'seed_city_eu_%' AND NOT EXISTS (SELECT 1 FROM Location l WHERE l.cityId=City.id);
--   DELETE FROM RegionTranslation WHERE id LIKE 'seed_rt_eu_%';
--   DELETE FROM Region WHERE id LIKE 'seed_region_eu_%' AND NOT EXISTS (SELECT 1 FROM City c WHERE c.regionId=Region.id);
--   DELETE FROM Country WHERE id IN ('seed_country_be','seed_country_ch','seed_country_gr','seed_country_no','seed_country_dk','seed_country_fi','seed_country_it') AND NOT EXISTS (SELECT 1 FROM City c WHERE c.countryId=Country.id) AND NOT EXISTS (SELECT 1 FROM Region r WHERE r.countryId=Country.id);
-- Apply (after a D1 Time Travel restore point is noted):
--   node scripts/project-identity-guard.mjs --project REGA && npx wrangler d1 execute rega24-migration --remote --file prisma/d1/data/20261029_europe_target_countries.sql
WITH v(code,en,ckb,kmr,de,fa,ar,tr,lat,lng) AS (VALUES ('BE','Belgium','بەلجیکا','Belçîka','Belgien','بلژیک','بلجيكا','Belçika',50.5039,4.4699),('CH','Switzerland','سویسرا','Swîsre','Schweiz','سوئیس','سويسرا','İsviçre',46.8182,8.2275),('GR','Greece','یۆنان','Yewnanistan','Griechenland','یونان','اليونان','Yunanistan',39.0742,21.8243),('NO','Norway','نەرویج','Norwêc','Norwegen','نروژ','النرويج','Norveç',60.472,8.4689),('DK','Denmark','دانیمارک','Danîmarka','Dänemark','دانمارک','الدنمارك','Danimarka',56.2639,9.5018),('FI','Finland','فینلەندا','Fînlenda','Finnland','فنلاند','فنلندا','Finlandiya',61.9241,25.7482),('IT','Italy','ئیتاڵیا','Îtalya','Italien','ایتالیا','إيطاليا','İtalya',41.8719,12.5674)) INSERT INTO Country (id,code,nameEn,nameCkb,nameKmr,nameDe,nameFa,nameAr,nameTr,latitude,longitude,isActive,sortOrder,createdAt) SELECT 'seed_country_'||lower(code),code,en,ckb,kmr,de,fa,ar,tr,lat,lng,1,0,1793232000000 FROM v WHERE NOT EXISTS (SELECT 1 FROM Country c WHERE c.code=v.code);
WITH v(cc,slug,en) AS (VALUES ('BE','brussels-capital','Brussels-Capital Region'),('CH','bern','Canton of Bern'),('GR','attica','Attica'),('NO','oslo','Oslo'),('DK','hovedstaden','Capital Region of Denmark'),('FI','uusimaa','Uusimaa'),('IT','lazio','Lazio')) INSERT INTO Region (id,countryId,slug,nameEn,isActive,sortOrder,createdAt,updatedAt) SELECT 'seed_region_eu_'||lower(cc)||'_'||slug,(SELECT id FROM Country WHERE code=v.cc),slug,en,1,0,1793232000000,1793232000000 FROM v WHERE NOT EXISTS (SELECT 1 FROM Region r WHERE r.countryId=(SELECT id FROM Country WHERE code=v.cc) AND r.slug=v.slug) AND EXISTS (SELECT 1 FROM Country WHERE code=v.cc);
WITH v(cc,slug,loc,name) AS (VALUES ('BE','brussels-capital','en','Brussels-Capital Region'),('BE','brussels-capital','de','Region Brüssel-Hauptstadt'),('CH','bern','en','Canton of Bern'),('CH','bern','de','Kanton Bern'),('GR','attica','en','Attica'),('GR','attica','de','Attika'),('NO','oslo','en','Oslo'),('NO','oslo','de','Oslo'),('DK','hovedstaden','en','Capital Region of Denmark'),('DK','hovedstaden','de','Region Hovedstaden'),('FI','uusimaa','en','Uusimaa'),('FI','uusimaa','de','Uusimaa'),('IT','lazio','en','Lazio'),('IT','lazio','de','Latium')), x AS (SELECT v.*, (SELECT r.id FROM Region r WHERE r.countryId=(SELECT id FROM Country WHERE code=v.cc) AND r.slug=v.slug) rid FROM v) INSERT INTO RegionTranslation (id,regionId,locale,name) SELECT 'seed_rt_eu_'||lower(cc)||'_'||slug||'_'||loc,rid,loc,name FROM x WHERE rid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM RegionTranslation t WHERE t.regionId=x.rid AND t.locale=x.loc);
WITH v(cc,slug,reg,en,ckb,kmr,de,fa,ar,tr,ord,lat,lng,fen,fkmr,fde,ftr) AS (VALUES ('BE','brussels','brussels-capital','Brussels','بڕوکسل','Brûksel','Brüssel','بروکسل','بروكسل','Brüksel',20,50.8503,4.3517,'brussels','brûksel','brüssel','brüksel'),('CH','bern','bern','Bern','بێرن','Bern','Bern','برن','برن','Bern',21,46.948,7.4474,'bern','bern','bern','bern'),('GR','athens','attica','Athens','ئەسینا','Atîna','Athen','آتن','أثينا','Atina',22,37.9838,23.7275,'athens','atîna','athen','atina'),('NO','oslo','oslo','Oslo','ئۆسلۆ','Oslo','Oslo','اسلو','أوسلو','Oslo',23,59.9139,10.7522,'oslo','oslo','oslo','oslo'),('DK','copenhagen','hovedstaden','Copenhagen','کۆپنهاگن','Kopenhag','Kopenhagen','کپنهاگ','كوبنهاغن','Kopenhag',24,55.6761,12.5683,'copenhagen','kopenhag','kopenhagen','kopenhag'),('FI','helsinki','uusimaa','Helsinki','هێلسینکی','Helsînkî','Helsinki','هلسینکی','هلسنكي','Helsinki',25,60.1699,24.9384,'helsinki','helsînkî','helsinki','helsinki'),('IT','rome','lazio','Rome','ڕۆما','Roma','Rom','رم','روما','Roma',26,41.9028,12.4964,'rome','roma','rom','roma')) INSERT INTO City (id,countryId,regionId,slug,nameEn,nameCkb,nameKmr,nameDe,nameFa,nameAr,nameTr,sortOrder,latitude,longitude,isActive,createdAt,updatedAt,foldedNameEn,foldedNameCkb,foldedNameKmr,foldedNameDe,foldedNameFa,foldedNameAr,foldedNameTr,foldedSlug) SELECT 'seed_city_eu_'||slug,(SELECT id FROM Country WHERE code=v.cc),(SELECT r.id FROM Region r WHERE r.countryId=(SELECT id FROM Country WHERE code=v.cc) AND r.slug=v.reg),slug,en,ckb,kmr,de,fa,ar,tr,ord,lat,lng,1,1793232000000,1793232000000,fen,ckb,fkmr,fde,fa,ar,ftr,slug FROM v WHERE NOT EXISTS (SELECT 1 FROM City c WHERE c.slug=v.slug OR (c.countryId=(SELECT id FROM Country WHERE code=v.cc) AND c.nameEn=v.en)) AND EXISTS (SELECT 1 FROM Country WHERE code=v.cc);
